document.addEventListener('pointerup',finishIconDrag);document.addEventListener('pointercancel',finishIconDrag);
desktop.addEventListener('click',e=>{if(e.target===desktop||e.target.classList.contains('wallpaper-shape')){state.selectedIcon=null;refresh();start.hidden=true;panel.hidden=true}});
let drag=null;document.addEventListener('pointerdown',e=>{const article=e.target.closest('.app-window');if(article&&article.dataset.windowId!==state.activeId)focusInPlace(article.dataset.windowId);const title=e.target.closest('.window-titlebar');if(title&&!e.target.closest('button')){const el=title.closest('.app-window'),id=el.dataset.windowId,w=state.windows.find(x=>x.id===id);if(w.maximized)return;focusInPlace(id);const live=document.querySelector(`[data-window-id="${id}"] .window-titlebar`);drag={id,dx:e.clientX-w.x,dy:e.clientY-w.y};live.setPointerCapture?.(e.pointerId);return}const grip=e.target.closest('.resize-grip');if(grip){const el=grip.closest('.app-window'),id=el.dataset.windowId,w=state.windows.find(x=>x.id===id);focusInPlace(id);drag={id,resize:true,x:e.clientX,y:e.clientY,width:w.width,height:w.height};e.preventDefault()}});
document.addEventListener('pointermove',e=>{if(!drag)return;const w=state.windows.find(x=>x.id===drag.id),el=document.querySelector(`[data-window-id="${drag.id}"]`);if(!w||!el)return;if(drag.resize){const maxWidth=Math.max(1,innerWidth-w.x),maxHeight=Math.max(1,innerHeight-70-w.y),minWidth=Math.min(applications[w.appId].minWidth,maxWidth),minHeight=Math.min(applications[w.appId].minHeight,maxHeight);w.width=Math.max(minWidth,Math.min(maxWidth,drag.width+e.clientX-drag.x));w.height=Math.max(minHeight,Math.min(maxHeight,drag.height+e.clientY-drag.y));el.style.setProperty('--w',`${w.width}px`);el.style.setProperty('--h',`${w.height}px`)}else{w.x=Math.max(0,Math.min(innerWidth-Math.min(w.width,innerWidth),e.clientX-drag.dx));w.y=Math.max(0,Math.min(innerHeight-70-Math.min(w.height,innerHeight-70),e.clientY-drag.dy));el.style.setProperty('--x',`${w.x}px`);el.style.setProperty('--y',`${w.y}px`)}});
document.addEventListener('pointerup',()=>{if(drag){geometryChanged(drag.id,{});drag=null}});
document.addEventListener('dblclick',e=>{const title=e.target.closest('.window-titlebar');if(!title||e.target.closest('button'))return;const win=title.closest('.app-window'),item=state.windows.find(w=>w.id===win?.dataset.windowId);if(item)maximizeWindow(item.id)});
$('#show-desktop')?.addEventListener('click',()=>{const open=state.windows.filter(w=>!w.minimized);if(open.length){state.hiddenWindows=open.map(w=>w.id);open.forEach(w=>w.minimized=true);state.activeId=null}else{(state.hiddenWindows??[]).forEach(id=>{const w=state.windows.find(x=>x.id===id);if(w)w.minimized=false});state.activeId=state.windows.find(w=>!w.minimized)?.id??null}refresh()});
if(state.preferences.showLock===false){setMode('desktop');root.dataset.mode='desktop'}
